BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TABLE IF NOT EXISTS public.pessoas (id uuid primary key default gen_random_uuid(), org_id uuid, nome text not null, email text, telefone text, cpf_cnpj text, tipo text not null default 'CLIENTE', ativo boolean not null default true, avatar_url text, foto_url text, genero text, profissao text, cargo text, empresa text, empresa_id uuid, data_inicio_wg date, notas text, cep text, logradouro text, numero text, complemento text, bairro text, cidade text, estado text, pais text default 'Brasil', drive_link text, obra_nome text, obra_endereco text, obra_status text, obra_tipo text, obra_area numeric(12,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), criado_em timestamptz not null default now());
DROP TRIGGER IF EXISTS trg_pessoas_updated_at ON public.pessoas;
CREATE TRIGGER trg_pessoas_updated_at BEFORE UPDATE ON public.pessoas FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX IF NOT EXISTS idx_pessoas_nome ON public.pessoas(nome);
CREATE INDEX IF NOT EXISTS idx_pessoas_tipo ON public.pessoas(tipo);
CREATE OR REPLACE VIEW public.clientes AS SELECT id,nome,email,telefone,cpf_cnpj,tipo AS tipo_cliente,CASE WHEN ativo THEN 'ativo' ELSE 'inativo' END AS status,ativo,avatar_url,foto_url,created_at,updated_at,criado_em FROM public.pessoas;
CREATE TABLE IF NOT EXISTS public.usuarios (id uuid primary key default gen_random_uuid(), auth_user_id uuid, pessoa_id uuid references public.pessoas(id) on delete set null, nome text, email text, tipo_usuario text not null default 'admin', role text, ativo boolean not null default true, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), criado_em timestamptz not null default now());
CREATE UNIQUE INDEX IF NOT EXISTS idx_usuarios_auth_user_id ON public.usuarios(auth_user_id) WHERE auth_user_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.nucleos (id uuid primary key default gen_random_uuid(), nome text not null, slug text unique, ativo boolean not null default true, ordem int not null default 0, created_at timestamptz not null default now());
INSERT INTO public.nucleos(nome,slug,ordem) VALUES ('Arquitetura','arquitetura',1),('Engenharia','engenharia',2),('Marcenaria','marcenaria',3) ON CONFLICT(slug) DO NOTHING;
CREATE TABLE IF NOT EXISTS public.pricelist_itens (id uuid primary key default gen_random_uuid(), codigo text, nome text not null, descricao text, categoria text, tipo text not null default 'servico', unidade text not null default 'un', valor_unitario numeric(14,2) not null default 0, nucleo text, ativo boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.oportunidades (id uuid primary key default gen_random_uuid(), org_id uuid, titulo text not null, nome text, descricao text, cliente_id uuid references public.pessoas(id) on delete set null, pessoa_id uuid references public.pessoas(id) on delete set null, responsavel_id uuid, estagio text default 'qualificacao', etapa text, valor numeric(14,2), probabilidade int, data_prev_fechamento date, fonte text, nucleo text, notas text, moeda text not null default 'BRL', status text not null default 'novo', origem text, data_abertura date default current_date, data_fechamento_prevista date, data_fechamento_real date, observacoes text, briefing_texto text, projeto_tipo text, projeto_path text, pipeline_status text default 'lead_novo', pipeline_updated timestamptz default now(), motivo_perda text, metadata jsonb not null default '{}'::jsonb, proposta_id uuid, analise_projeto_id uuid, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_oportunidades_cliente ON public.oportunidades(cliente_id);
CREATE TABLE IF NOT EXISTS public.propostas (id uuid primary key default gen_random_uuid(), org_id uuid, cliente_id uuid references public.pessoas(id) on delete set null, pessoa_id uuid references public.pessoas(id) on delete set null, oportunidade_id uuid references public.oportunidades(id) on delete set null, analise_projeto_id uuid, nucleo text, nucleo_id uuid, numero text unique, titulo text not null, descricao text, forma_pagamento text default 'a_vista', percentual_entrada numeric(8,4), numero_parcelas int, validade_dias int default 7, prazo_execucao_dias int, validade date, valor_materiais numeric(14,2) not null default 0, valor_mao_obra numeric(14,2) not null default 0, valor_total numeric(14,2) not null default 0, exibir_valores boolean not null default true, pagamento_cartao boolean default false, status text not null default 'rascunho', observacoes text, notas text, pdf_url text, token_compartilhamento uuid unique, token_expira_em timestamptz, enviada_em timestamptz, enviada_para text, enviada_via text, visualizada_em timestamptz, aprovada_em timestamptz, rejeitada_em timestamptz, motivo_rejeicao text, solicitacao_revisao text, arquivada_em timestamptz, created_by uuid, usuario_id uuid, responsavel_id uuid, empresa_id uuid, criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_propostas_cliente ON public.propostas(cliente_id);
CREATE INDEX IF NOT EXISTS idx_propostas_token ON public.propostas(token_compartilhamento) WHERE token_compartilhamento IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.propostas_itens (id uuid primary key default gen_random_uuid(), proposta_id uuid not null references public.propostas(id) on delete cascade, pricelist_item_id uuid references public.pricelist_itens(id) on delete set null, nome text not null, descricao text, descricao_customizada text, codigo text, categoria text, tipo text not null default 'servico', contratado_pelo_cliente boolean not null default false, unidade text not null default 'un', quantidade numeric(14,4) not null default 1, valor_unitario numeric(14,2) not null default 0, valor_subtotal numeric(14,2) not null default 0, ordem int default 0, nucleo text, ambiente_id uuid, prioridade text, status_item text default 'ativo', criado_em timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_propostas_itens_proposta ON public.propostas_itens(proposta_id);
CREATE OR REPLACE FUNCTION public.gerar_numero_proposta() RETURNS text LANGUAGE plpgsql AS $$ DECLARE v_num int; BEGIN SELECT COALESCE(MAX(NULLIF(regexp_replace(numero,'\D','','g'),'')::int),0)+1 INTO v_num FROM public.propostas WHERE numero IS NOT NULL; RETURN 'PROP-'||to_char(now(),'YYYY')||'-'||lpad(v_num::text,4,'0'); END; $$;
CREATE OR REPLACE VIEW public.vw_propostas_detalhadas AS SELECT p.*, COALESCE(pc.nome,pp.nome) nome_cliente_resolvido, COALESCE(pc.avatar_url,pp.avatar_url,pc.foto_url,pp.foto_url) cliente_avatar_url, COALESCE(pc.foto_url,pp.foto_url,pc.avatar_url,pp.avatar_url) cliente_foto_url, COALESCE(pc.email,pp.email) email_cliente_resolvido, u.nome criador_nome FROM public.propostas p LEFT JOIN public.pessoas pc ON pc.id=p.cliente_id LEFT JOIN public.pessoas pp ON pp.id=p.pessoa_id LEFT JOIN public.usuarios u ON u.id=COALESCE(p.created_by,p.usuario_id,p.responsavel_id);
CREATE TABLE IF NOT EXISTS public.contratos (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, oportunidade_id uuid references public.oportunidades(id) on delete set null, proposta_id uuid references public.propostas(id) on delete set null, numero text, titulo text, status text not null default 'rascunho', valor_total numeric(14,2) not null default 0, unidade_negocio text, criado_em timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.contratos_nucleos (id uuid primary key default gen_random_uuid(), contrato_id uuid not null references public.contratos(id) on delete cascade, nucleo text not null, status text not null default 'ativo', created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.projetos (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, contrato_id uuid references public.contratos(id) on delete set null, oportunidade_id uuid references public.oportunidades(id) on delete set null, nome text not null, status text not null default 'ativo', nucleo text, progresso numeric(6,2) not null default 0, criado_em timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.cronograma_tarefas (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, projeto_id uuid references public.projetos(id) on delete cascade, titulo text not null, descricao text, status text not null default 'pendente', nucleo text, data_inicio date, data_fim date, ordem int not null default 0, criado_em timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.checklists (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, projeto_id uuid references public.projetos(id) on delete cascade, titulo text not null, status text not null default 'ativo', created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.checklist_itens (id uuid primary key default gen_random_uuid(), checklist_id uuid references public.checklists(id) on delete cascade, titulo text not null, status text not null default 'pendente', ordem int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.cliente_checklists (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete cascade, titulo text not null, status text not null default 'ativo', created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.cliente_checklist_items (id uuid primary key default gen_random_uuid(), checklist_id uuid references public.cliente_checklists(id) on delete cascade, titulo text not null, status text not null default 'pendente', ordem int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.solicitacoes_cliente (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, titulo text not null, descricao text, status text not null default 'aberta', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.cliente_moodboards (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, titulo text not null, status text not null default 'ativo', itens jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.etapas_escolha (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, titulo text not null, status text not null default 'pendente', ordem int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.notas_sistema (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, titulo text, conteudo text, tipo text, created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.documentos (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, projeto_id uuid references public.projetos(id) on delete set null, nome text not null, url text, tipo text, created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.financeiro_lancamentos (id uuid primary key default gen_random_uuid(), cliente_id uuid references public.pessoas(id) on delete set null, contrato_id uuid references public.contratos(id) on delete set null, descricao text not null, valor numeric(14,2) not null default 0, status text not null default 'pendente', vencimento date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS public.saas_leads_landing (id uuid primary key default gen_random_uuid(), nome text, email text, empresa text, mensagem text, origem text, status text not null default 'novo', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
COMMIT;
